};

export function icon(name) {
  const spec = ICON[name];
  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('viewBox', '0 0 16 16');
  svg.setAttribute('aria-hidden', 'true');
  const p = document.createElementNS(NS, 'path');
  p.setAttribute('d', spec.d);
  if (spec.stroke) {
    p.setAttribute('fill', 'none');
    p.setAttribute('stroke', 'currentColor');
    p.setAttribute('stroke-width', String(spec.stroke));
    p.setAttribute('stroke-linecap', 'round');
    p.setAttribute('stroke-linejoin', 'round');
  } else p.setAttribute('fill', 'currentColor');
  svg.append(p);
  return svg;
}

// `name` is an icon name, or any other string to use as a glyph. The entry popup's rows are
// icons throughout; only the top pane's zoom pair and arrows are characters.
export function iconBtn(name, label, cls = '') {
  const b = el('button', ['ib', cls].filter(Boolean).join(' '));
  b.type = 'button';
  b.title = label;
  b.setAttribute('aria-label', label);
  b.append(ICON[name] ? icon(name) : el('span', 'glyph', name));
  return b;
}

// ---- popovers ------------------------------------------------------------------------------

export function openPop(pop, anchor, align = 'left') {
  pop.hidden = false;
  $('#scrim').hidden = false;
  const r = anchor.getBoundingClientRect();
  const w = pop.offsetWidth;
  const left = align === 'right' ? r.right - w : r.left;
  pop.style.left = `${Math.max(8, Math.min(left, innerWidth - w - 8))}px`;
  pop.style.top = `${r.bottom + 6}px`;
  anchor.setAttribute?.('aria-expanded', 'true');
}

const POPS = ['#picker', '#filter-pop', '#day-pop', '#settings-sheet'];

export function closePops() {
  for (const id of [...POPS, '#scrim']) $(id).hidden = true;
  for (const id of ['#period', '#filter-btn']) $(id).setAttribute('aria-expanded', 'false');
}

// The shell: the top pane, navigation, the date picker, the group filter, the sync line, and
// which view the big calendar window holds.
import { getConfig, getKV, setKV, queuedCount } from '../shared/store.js';
import { pull, drain } from '../shared/github.js';
import {
  loadModel, todayKey, addDays, addMonths, partsOf, monthGrid, weekStartOf, isoWeek, setZone,
  sprintRange, sprintOf
} from './data.js';
import {
  S, $, el, phone, colorOf, labelOf, dayLabel, icon, currentSprint, openPop, closePops
} from './ui.js';
import { renderView, wireView, openDayPop } from './views.js';
import { renderKanban } from './kanban.js';
import { closePopup } from './popup.js';
import { openSettings } from './settings.js';
import { loadPrefs, applyTheme, weekdayName } from '../shared/prefs.js';

let pick = { mode: 'days', y: 2026, m: 0, base: 0 };

// ---- rendering -----------------------------------------------------------------------------

function render() {
  const k = S.view.mode === 'K';
  $('#period-label').textContent = periodLabel();

  // One slot carries the way to the other kind of view, and the zoom pair is not shown on the
  // board because the board is not a zoom step.
  $('#board').replaceChildren(icon(k ? 'cal' : 'board'));
  $('#board').setAttribute('aria-label', k ? 'Back to the month view' : 'Kanban');
  for (const [id, dir] of [['#zoom-out', -1], ['#zoom-in', 1]]) {
    $(id).hidden = k;
    $(id).disabled = !k && !ZOOM[ZOOM.indexOf(S.view.mode) + dir];
  }

  if (k) renderKanban($('#view'));
  else renderView($('#view'));
  renderFilter();
}

// The pane has to fit a phone, so every label is short. The month name is the device locale's
// abbreviation, upper-cased - short beats English.
const shortMonth = key => new Date(`${key}T12:00:00`)
  .toLocaleDateString(undefined, { month: 'short' }).replace(/\./g, '').toUpperCase();

function periodLabel() {
  const { mode, anchor } = S.view;
  const [y, , d] = partsOf(anchor);
  if (mode === 'D')
    return `${weekdayName(anchor, 'short').slice(0, 2).toUpperCase()} ${d}/${shortMonth(anchor)}`;
  if (mode === 'W') {
    // The ISO number is in the label whether or not the gutter is on, and the month is the one
    // the row's fourth day is in - the rule the gutter uses, so the two cannot disagree.
    const a = weekStartOf(anchor, S.prefs.weekStart);
    return `W${isoWeek(addDays(a, 3))}/${shortMonth(addDays(a, 3))}`;
  }
  if (mode === 'M') return `${shortMonth(anchor)}/${String(y).slice(2)}`;
  if (mode === 'Y') return String(y);
  return String(S.view.sprint);
}

// ---- navigation ----------------------------------------------------------------------------

// The calendar's zoom, outermost first. `+` zooms in towards the day and is disabled at the
// end of the scale rather than wrapping.
const ZOOM = ['Y', 'M', 'W', 'D'];

function zoom(dir) {
  const next = ZOOM[ZOOM.indexOf(S.view.mode) + dir];
  if (!next) return;
  S.view.mode = next;
  closePops();
  render();
}
$('#zoom-out').addEventListener('click', () => zoom(-1));
$('#zoom-in').addEventListener('click', () => zoom(1));

$('#board').addEventListener('click', () => {
  if (S.view.mode === 'K') S.view.mode = 'M';
  else {
    S.view.mode = 'K';
    S.view.sprint = sprintOf(S.view.anchor, S.model.settings) || currentSprint();
  }
  closePops();
  render();
});

function step(dir) {
  const v = S.view;
  if (v.mode === 'D') v.anchor = addDays(v.anchor, dir);
  else if (v.mode === 'W') v.anchor = addDays(v.anchor, 7 * dir);
  else if (v.mode === 'M') v.anchor = addMonths(v.anchor, dir);
  else if (v.mode === 'Y') v.anchor = addMonths(v.anchor, 12 * dir);
  else v.sprint = Math.max(1, v.sprint + dir);
  closePops();
  render();
}
$('#prev').addEventListener('click', () => step(-1));
$('#next').addEventListener('click', () => step(1));

// There is no jump-to-today button and no `+` in the pane: today is the highlighted day in the
// dropdown, and an entry is created where it will live - a cell, the day preview, or a kanban
// column header.

$('#home').append(icon('house'));
$('#gear').addEventListener('click', openSettings);
$('#settings-close').addEventListener('click', closePops);

// ---- the dropdown date picker --------------------------------------------------------------
// A month at a time, a 9-year grid, or - in the kanban - a list of sprints.

$('#period').addEventListener('click', () => {
  if (!$('#picker').hidden) return closePops();
  closePops();
  const [y, m] = partsOf(S.view.anchor);
  pick = S.view.mode === 'K'
    ? { mode: 'sprints', base: Math.max(1, S.view.sprint - 4) }
    : { mode: 'days', y, m: m - 1, base: y - 8 };
  renderPicker();
  openPop($('#picker'), $('#period'));
});

$('#pick-title').addEventListener('click', () => {
  if (pick.mode === 'sprints') return;
  pick.mode = pick.mode === 'days' ? 'years' : 'days';
  pick.base = pick.y - 8;
  renderPicker();
});
$('#pick-prev').addEventListener('click', () => pagePicker(-1));
$('#pick-next').addEventListener('click', () => pagePicker(1));

function pagePicker(dir) {
  if (pick.mode === 'years') pick.base += dir * 9;
  else if (pick.mode === 'sprints') pick.base = Math.max(1, pick.base + dir * 9);
  else {
    const m = pick.m + dir;
    pick.y += Math.floor(m / 12);
    pick.m = (m + 12) % 12;
  }
  renderPicker();
}

function renderPicker() {
  const body = $('#pick-body');

  if (pick.mode === 'sprints') {
    $('#pick-label').textContent = 'Sprints';
    body.className = 'pick-body sprints';
    body.replaceChildren(...Array.from({ length: 9 }, (_, i) => {
      const r = sprintRange(pick.base + i, S.model.settings);
      // The sprint today falls in reads `current` and carries the brighter background; the
      // selected one is marked, not renamed, so the two can be the same row.
      const cur = r.n === currentSprint();
      const b = el('button', `pk wide${cur ? ' cur' : ''}${r.n === S.view.sprint ? ' now' : ''}`,
        `${cur ? 'current' : `Sprint ${r.n}`} · ${dayLabel(r.start)} – ${dayLabel(r.end)}`);
      b.type = 'button';
      b.addEventListener('click', () => {
        closePops();
        S.view.sprint = r.n;
        S.view.anchor = r.start;
        render();
      });
      return b;
    }));
    return;
  }

  if (pick.mode === 'years') {
    // 9 years ending with the current one; the arrows page by 9.
    $('#pick-label').textContent = `${pick.base} – ${pick.base + 8}`;
    body.className = 'pick-body years';
    body.replaceChildren(...Array.from({ length: 9 }, (_, i) => {
      const y = pick.base + i;
      const b = el('button', `pk${y === partsOf(S.view.anchor)[0] ? ' now' : ''}`, String(y));
      b.type = 'button';
      b.addEventListener('click', () => { pick = { ...pick, mode: 'days', y }; renderPicker(); });
      return b;
    }));
    return;
  }

  $('#pick-label').textContent =
    new Date(pick.y, pick.m, 1, 12).toLocaleDateString(undefined, { month: 'long', year: 'numeric' });
  body.className = 'pick-body days';
  body.replaceChildren(
    ...weekLetters().map(n => el('span', 'wh', n)),
    ...monthGrid(pick.y, pick.m, S.prefs.weekStart).map(k => {
      const [, mm, dd] = partsOf(k);
      const b = el('button', `pk${mm !== pick.m + 1 ? ' out' : ''}${k === todayKey() ? ' now' : ''}`,
        String(dd));
      b.type = 'button';
      b.addEventListener('click', () => {
        closePops();
        S.view.anchor = k;
        render();
        // Picking a date in a view that cannot show the day's entries in place opens the preview.
        if (S.view.mode === 'Y' || (S.view.mode === 'M' && phone())) openDayPop(k);
      });
      return b;
    }));
}

const weekLetters = () => {
  const base = weekStartOf('2026-01-05', S.prefs.weekStart);
  return Array.from({ length: 7 }, (_, i) =>
    new Date(`${addDays(base, i)}T12:00:00`).toLocaleDateString(undefined, { weekday: 'narrow' }));
};

// ---- the filter ----------------------------------------------------------------------------
// A view filter, remembered per device. Groups are named and coloured in settings, not here.

function groupNames() {
  const names = new Set(Object.keys(S.model.groups));
  let ungrouped = false;
  for (const e of [...S.model.dated, ...S.model.rules]) {
    if (e.data.group) names.add(e.data.group); else ungrouped = true;
  }
  const out = [...names].sort().map(n => [n, labelOf(n)]);
  if (ungrouped) out.push(['', 'no group']);
  return out;
}

function renderFilter() {
  const kids = [el('div', 'pop-sub', 'Groups')];
  for (const [name, label] of groupNames()) {
    const lab = el('label', 'glab');
    const box = el('input');
    box.type = 'checkbox';
    box.checked = !S.hidden.has(name);
    box.addEventListener('change', async () => {
      if (box.checked) S.hidden.delete(name); else S.hidden.add(name);
      await setKV('calendar.hiddenGroups', [...S.hidden]);
      render();
    });
    const sw = el('span', 'swatch');
    sw.style.background = colorOf(name);
    lab.append(box, sw, el('span', '', label || name));
    kids.push(lab);
  }

  // Priority and assignee narrow the board, where a sprint can hold more cards than fit.
  if (S.view.mode === 'K') {
    kids.push(el('div', 'pop-sub', 'Priority'));
    const chips = el('div', 'chiprow');
    for (const [v, text] of [[1, 'P1'], [2, 'P2'], [3, 'P3'], [0, 'none']]) {
      const b = el('button', `chip p${v}${S.kfilter.priority.has(v) ? ' on' : ''}`, text);
      b.type = 'button';
      b.addEventListener('click', () => {
        if (S.kfilter.priority.has(v)) S.kfilter.priority.delete(v); else S.kfilter.priority.add(v);
        render();
      });
      chips.append(b);
    }
    kids.push(chips, el('div', 'pop-sub', 'Assignee'));
    const people = [...new Set([...S.model.dated, ...S.model.rules]
      .flatMap(e => [].concat(e.data.participants ?? []).map(String)))].sort();
    const sel = el('select');
    for (const [v, text] of [['', 'anyone'], ...people.map(p => [p, p])]) {
      const o = el('option', '', text);
      o.value = v;
      if (v === S.kfilter.assignee) o.selected = true;
      sel.append(o);
    }
    sel.addEventListener('change', () => { S.kfilter.assignee = sel.value; render(); });
    kids.push(sel);
  }

  $('#filter-body').replaceChildren(...kids);
}

$('#filter-btn').addEventListener('click', () => {
  if (!$('#filter-pop').hidden) return closePops();
  closePops();
  openPop($('#filter-pop'), $('#filter-btn'), 'right');
});

$('#scrim').addEventListener('click', closePops);
addEventListener('keydown', e => {
  if (e.key !== 'Escape') return;
  if (!$('#sub').hidden) $('#sub-cancel').click();
  else if (!$('#popup').hidden) closePopup();
  else closePops();
});
matchMedia('(min-width: 600px)').addEventListener('change', () => { closePops(); render(); });

// ---- sync ----------------------------------------------------------------------------------

function status(text, bad) {
  const s = $('#sync');
  s.textContent = text;
  s.classList.toggle('bad', !!bad);
}

async function showSync() {
  const n = await queuedCount();
  status(n ? `${n} change(s) pending` : 'in sync');
}

// Every write reaches the local mirror first, so the view is already right and the push can run
// behind it. One drain at a time, and failures and conflicts are reported here rather than in
// the popup the user has already left.
let chain = Promise.resolve();
function push(message) {
  chain = chain.then(async () => {
    status('pushing…');
    try {
      const r = await drain(message);
      if (r.conflicts?.length)
        status(`${r.conflicts.length} change(s) kept beside the remote version as .conflict files — review them`, true);
      else await showSync();
    } catch (err) {
      status(`not pushed: ${err.message}`, true);
    }
  });
}

async function refresh() {
  if (await queuedCount()) return showSync();
  status('checking…');
  try {
    const r = await pull();                    // whole repo: the mirror and the ETag are shared
    if (!r.unchanged) { S.model = await loadModel(); render(); }
    status(r.empty ? 'repo is empty' : r.unchanged ? 'in sync' : `in sync — ${r.changed} file(s) updated`);
  } catch (err) {
    status(err.message, true);
  }
}

// ---- boot ----------------------------------------------------------------------------------

S.render = render;
S.status = status;
S.push = push;
S.reload = loadModel;
wireView();

const minePrefs = await loadPrefs();
applyTheme(minePrefs.theme);

if (!await getConfig()) {
  $('#needs-setup').hidden = false;
} else {
  $('#cal').hidden = false;
  S.prefs = {
    ...S.prefs, ...minePrefs,
    weekStart: (await getKV('calendar.weekStart')) ?? 1,
    showWeeks: !!(await getKV('calendar.showWeeks')),
    timeZone: (await getKV('calendar.timeZone')) || ''
  };
  setZone(S.prefs.timeZone);
  S.hidden = new Set(await getKV('calendar.hiddenGroups') || []);
  S.model = await loadModel();
  S.view.anchor = todayKey();
  S.view.sprint = currentSprint();
  render();
  await refresh();
  addEventListener('focus', refresh);
}

// The entry popup. A row of icon buttons at the top, the title, the stage and the dates, then
// one row per field that is set.
//
// Each field button opens a sub-popup, and a sub-popup only ever writes into the draft held
// here - nothing reaches the repo until the entry popup's own disk, so one entry edit is one
// commit and the popup's x discards the staged fields with everything else. It is also what
// makes a brand-new entry work, since it has no file for a sub-popup to write to. The one
// exception is adding a category, which is a different file: see below.
import {
  isAllDay, todayKey, toInstant, wallParts, dowOf, partsOf, STAGES, createEntry, updateEntry,
  deleteEntry, saveOverride, skipOccurrence, createGroup, priorityOf
} from './data.js';
import { S, $, el, iconBtn, labelOf, inkOn, STAGE_COLOR } from './ui.js';

const pad = n => String(n).padStart(2, '0');
const splitList = v => String(v).split(/[,;\s]+/).map(s => s.trim()).filter(Boolean);

// Keys the form owns. Anything else in the file - exdate, rdate, status, a hand-added key -
// survives a save untouched. `done` is in the list and never written back out again.
const FORM_KEYS = ['title', 'type', 'start', 'end', 'done', 'stage', 'priority', 'estimate',
  'group', 'location', 'recurrence', 'alerts', 'participants'];

let D = null;      // the draft
let sub = null;    // the open sub-popup: { field, read }

// ---- the fields behind the icons ------------------------------------------------------------

// The order is the same on a task as on an event, so the row does not reshuffle when the type
// changes - and the detail rows below follow it, which puts participants at the bottom.
const FIELDS = [
  { k: 'body', ic: 'lines', label: 'Details', empty: '',
    set: v => !!v.trim(), sum: v => v.trim().split('\n').find(Boolean) || '', ed: bodyEditor },
  { k: 'group', ic: 'ball', label: 'Category', empty: '',
    set: v => !!v, sum: v => labelOf(v), ed: groupPicker },
  { k: 'recurrence', ic: 'repeat', label: 'Repeat', empty: '',
    set: v => !!v, sum: v => ruleText(v), ed: recurrenceEditor },
  { k: 'alerts', ic: 'bell', label: 'Alerts', empty: [],
    set: v => v.length > 0, sum: v => v.map(alertText).join(', '), ed: alertsEditor },
  { k: 'location', ic: 'pin', label: 'Location', empty: '',
    set: v => !!v, sum: v => v, ed: textEditor('Where', 'Conference room 3B') },
  { k: 'participants', ic: 'person', label: 'Participants', empty: [],
    set: v => v.length > 0, sum: v => v.join(', '), ed: participantsEditor }
];

// The estimate has a sub-popup but no place in D.v, so the sub reads and writes through these
// two rather than reaching into D.v itself.
const EST = { k: 'estimate', label: 'Estimate', empty: null, ed: estimateEditor };
const readField = f => f.k === 'estimate' ? D.estimate : D.v[f.k];
const writeField = (f, v) => { if (f.k === 'estimate') D.estimate = v; else D.v[f.k] = v; };

const alertText = n => n === 0 ? 'at start' : `${n} min before`;

// Only the series carries the rule: an occurrence override must never rewrite it.
const canRule = () => !D.occ || D.scope === 'series' || !D.occ.seriesId;

// ---- opening -------------------------------------------------------------------------------

export function openNew(seed = {}) {
  open(null, 'occurrence', seed);
}

export function openEntry(occ) {
  if (occ) open(occ, 'occurrence', {});
}

function open(occ, scope, seed) {
  D = draft(occ, scope, seed);
  $('#popup').hidden = false;
  $('#f-msg').textContent = '';
  fillForm();
  requestAnimationFrame(() => $('#f-title').focus());
}

function draft(occ, scope, seed) {
  const series = occ && occ.seriesId && scope === 'series';
  const data = occ ? (series ? occ.seriesData : occ.data) : {};
  const body = occ ? (series ? occ.seriesBody : occ.body) : '';
  const start = String(data.start ?? '');
  const allDay = occ ? isAllDay(start) : !!seed.allDay;
  const day = occ ? '' : (seed.dayKey || todayKey());
  const hour = seed.hour == null ? 9 : seed.hour;

  const [sd, st] = occ && !allDay ? wallParts(start) : [occ ? start.slice(0, 10) : day, `${pad(hour)}:00`];
  let ed = '', et = '';
  if (occ && data.end != null) [ed, et] = allDay ? [String(data.end).slice(0, 10), ''] : wallParts(String(data.end));
  else if (!occ && !allDay) [ed, et] = [day, `${pad(Math.min(23, hour + 1))}:00`];

  return {
    occ, scope, base: data,
    type: occ ? (data.type === 'task' ? 'task' : 'event') : (seed.type || 'event'),
    stage: occ ? (occ.stage || 'todo') : (seed.stage || 'todo'),
    priority: occ ? occ.priority : null,
    estimate: occ ? (occ.estimate ?? null) : 1,
    title: occ ? String(data.title ?? '') : '',
    allDay, startDate: sd, startTime: allDay ? '' : st, endDate: ed, endTime: allDay ? '' : et,
    v: {
      recurrence: occ && (series || !occ.seriesId) ? String(data.recurrence ?? '') : '',
      group: String(data.group ?? ''),
      location: String(data.location ?? ''),
      alerts: list(data.alerts).map(Number).filter(Number.isFinite),
      participants: list(data.participants).map(String),
      body: body ?? ''
    }
  };
}

const list = v => v == null ? [] : Array.isArray(v) ? v : [v];

export function closePopup() {
  closeSub();
  $('#popup').hidden = true;
  D = null;
}

// ---- drawing -------------------------------------------------------------------------------

function fillForm() {
  iconRow();

  $('#f-title').value = D.title;
  $('#f-scope').hidden = !(D.occ && D.occ.seriesId);
  for (const b of document.querySelectorAll('[data-scope]'))
    b.setAttribute('aria-pressed', String(b.dataset.scope === D.scope));

  flagsRow();
  $('#f-start-date').value = D.startDate;
  $('#f-start-time').value = D.startTime;
  $('#f-end-date').value = D.endDate;
  $('#f-end-time').value = D.endTime;
  $('#f-start-time').disabled = D.allDay;
  $('#f-end-time').disabled = D.allDay;

  detailRows();

  const isOcc = D.occ && D.occ.seriesId && D.scope === 'occurrence';
  $('#f-skip').hidden = !isOcc;
  $('#f-path').textContent = !D.occ ? 'New entry.'
    : D.scope === 'series' && D.occ.seriesId ? D.occ.seriesPath
      : isOcc ? `${D.occ.seriesPath} · occurrence ${D.occ.recId}${D.occ.override ? ` · override ${D.occ.path}` : ''}`
        : D.occ.path;
}

// A ticked square and a calendar page choose the type, then a short vertical dash, then the six
// field icons, which open their popups. Every button is an icon; none carries a letter. An icon
// whose field is set is shown enabled, so the row doubles as a summary of what the entry carries.
function iconRow() {
  const kids = [];
  for (const [t, ic, label] of [['task', 'check', 'Task'], ['event', 'cal', 'Event']]) {
    const b = iconBtn(ic, label, D.type === t ? 'on' : '');
    b.setAttribute('aria-pressed', String(D.type === t));
    b.addEventListener('click', () => { D.type = t; fillForm(); });
    kids.push(b);
  }
  // What the entry is comes first and governs the rest, so it is set apart from it.
  kids.push(el('span', 'vdash'));
  for (const f of FIELDS) {
    const b = iconBtn(f.ic, f.label, f.set(D.v[f.k]) ? 'on' : '');
    if (f.k === 'recurrence' && !canRule()) b.disabled = true;
    b.addEventListener('click', () => openSub(f));
    kids.push(b);
  }
  kids.push(el('span', 'spacer'));

  const x = iconBtn('x', 'Close and discard');
  x.addEventListener('click', closePopup);
  kids.push(x);
  if (D.occ) {
    const t = iconBtn('trash', D.occ.seriesId ? 'Delete the whole repeating entry' : 'Delete',
      'bad');
    t.addEventListener('click', removeEntry);
    kids.push(t);
  }
  const disk = iconBtn('disk', 'Save', 'primary');
  disk.type = 'submit';
  kids.push(disk);

  $('#f-icons').replaceChildren(...kids);
}

// The all-day row: a sun, and on a task stage, priority and estimate beside it.
function flagsRow() {
  const kids = [allDayBtn()];
  if (D.type === 'task') kids.push(stageBtn(), prioBtn(), estBtn());
  $('#f-flags').replaceChildren(...kids);
}

// All-day is a clickable icon rather than a checkbox, and it lights with the ordinary enabled
// background - deliberately not the save button's green, which in Mine means a save.
function allDayBtn() {
  const b = iconBtn('sun', 'All-day', D.allDay ? 'on' : '');
  b.setAttribute('aria-pressed', String(D.allDay));
  b.addEventListener('click', () => {
    D.allDay = !D.allDay;
    if (D.allDay) { D.startTime = ''; D.endTime = ''; }
    else { D.startTime = D.startTime || '09:00'; D.endTime = D.endTime || '10:00'; }
    fillForm();
  });
  return b;
}

// Stage, priority and estimate are three small values rather than fields with a form each, so
// they are edited in the row itself and show their value - as a badge on the icon's corner,
// which is why the enabled rule above is about the six field icons alone. Only the estimate
// opens a popup, because a number has to be typed.
const badged = (b, text, cls, color) => {
  const s = el('span', ['badge', cls].filter(Boolean).join(' '), text);
  if (color) { s.style.background = color; s.style.color = inkOn(color); }
  b.append(s);
  return b;
};

function stageBtn() {
  const b = badged(iconBtn('cols', `Stage: ${D.stage}`), '', '', STAGE_COLOR[D.stage]);
  b.addEventListener('click', () => {
    D.stage = STAGES[(STAGES.indexOf(D.stage) + 1) % STAGES.length];
    fillForm();
  });
  return b;
}

function prioBtn() {
  const p = D.priority ?? 0;
  const b = iconBtn('flag', `Priority: ${p || 'none'}`);
  if (p) badged(b, String(p), `p${p}`);
  b.addEventListener('click', () => { D.priority = p === 3 ? null : p + 1; fillForm(); });
  return b;
}

function estBtn() {
  const b = iconBtn('glass', `Estimate: ${D.estimate ? `${D.estimate} day(s)` : 'none'}`);
  if (D.estimate) badged(b, `${D.estimate}d`, 'wide');
  b.addEventListener('click', () => openSub(EST));
  return b;
}

// One row per field that is set, in the order of the icons above - so a location that has been
// given appears at the bottom. A pen reopens its popup, a trashcan clears it.
function detailRows() {
  const rows = [];
  for (const f of FIELDS) {
    if (!f.set(D.v[f.k])) continue;
    if (f.k === 'recurrence' && !canRule()) continue;
    const row = el('div', 'frow');
    row.append(el('span', 'flab', f.label), el('span', 'fval', f.sum(D.v[f.k])));
    const pen = iconBtn('pen', `Edit ${f.label}`);
    pen.addEventListener('click', () => openSub(f));
    const tr = iconBtn('trash', `Clear ${f.label}`, 'bad');
    tr.addEventListener('click', () => { D.v[f.k] = f.empty; fillForm(); });
    row.append(pen, tr);
    rows.push(row);
  }
  $('#f-rows').replaceChildren(...rows);
}

// ---- sub-popups ----------------------------------------------------------------------------

function openSub(f) {
  const ed = f.ed(readField(f));
  sub = { f, read: ed.read };
  $('#sub-title').textContent = f.label;
  $('#sub-body').replaceChildren(ed.node);
  $('#sub').hidden = false;
  $('#sub-scrim').hidden = false;
  requestAnimationFrame(() => $('#sub-body').querySelector('input, select, textarea')?.focus());
}

function closeSub() {
  $('#sub').hidden = true;
  $('#sub-scrim').hidden = true;
  sub = null;
}

// Every sub-popup has the same three: a trashcan that clears that one field, an x that abandons
// the sub-edit, and a disk that commits the value into the draft and lights the icon.
$('#sub-clear').addEventListener('click', () => {
  writeField(sub.f, sub.f.empty);
  closeSub();
  fillForm();
});
$('#sub-cancel').addEventListener('click', closeSub);
$('#sub-ok').addEventListener('click', () => {
  const v = sub.read();
  if (v !== undefined) writeField(sub.f, v);
  closeSub();
  fillForm();
});
$('#sub-scrim').addEventListener('click', closeSub);

// ---- the editors ---------------------------------------------------------------------------

function field(labelText, control, hint) {
  const l = el('label', '', labelText);
  l.append(control);
  if (hint) l.append(el('small', '', hint));
  return l;
}

// A declaration, not a const arrow: FIELDS calls this while the module is still evaluating.
function textEditor(labelText, placeholder) {
  return cur => {
    const i = el('input');
    i.value = cur || '';
    i.placeholder = placeholder;
    return { node: field(labelText, i), read: () => i.value.trim() };
  };
}

function estimateEditor(cur) {
  const i = el('input');
  i.type = 'number';
  i.min = '0';
  i.step = '0.5';
  i.inputMode = 'decimal';
  i.value = cur ?? '';
  return {
    node: field('Days', i, 'Cleared, the task simply has no estimate.'),
    read: () => { const n = Number(i.value); return Number.isFinite(n) && n > 0 ? n : null; }
  };
}

function alertsEditor(cur) {
  const i = el('input');
  i.inputMode = 'numeric';
  i.placeholder = '0, 15';
  i.value = (cur || []).join(', ');
  return {
    node: field('Minutes before start', i,
      '0 is at start. Stored and exported only — nothing fires while the app is closed.'),
    read: () => splitList(i.value).map(Number).filter(Number.isFinite)
  };
