  color: var(--fg); background: none; border: 0; white-space: nowrap;
}
#period-label { overflow: hidden; text-overflow: ellipsis; }
.caret { flex: none; margin-left: .3rem; font-size: .7rem; opacity: .6; }

/* The zoom pair and the two single-glyph navs sit flush, like one control. */
.topbar .nav.ic svg { width: 1.05rem; height: 1.05rem; display: block; }
.mode {
  width: auto; min-width: 1.7rem; margin: 0; padding: .45rem .2rem;
