  color: var(--fg); background: var(--soft); border: 0; border-radius: 0;
}
.mode:first-child { border-radius: .5rem 0 0 .5rem; }
.mode:last-child { border-radius: 0 .5rem .5rem 0; }
.mode[aria-pressed="true"] { color: var(--bg); background: var(--accent); }

.view { flex: 1; min-height: 0; }
